//! The emoji list. The statics at the bottom are generated by `build.rs` from
//! `data/emojis.json`, Fluxer's own list.

use std::borrow::Cow;
use std::collections::HashMap;
use std::sync::OnceLock;

/// The picker's sections, in Fluxer's order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Category {
    People,
    Nature,
    Food,
    Activity,
    Travel,
    Objects,
    Symbols,
    Flags,
}

impl Category {
    /// Every category, in picker order.
    pub const ALL: [Category; 8] = [
        Category::People,
        Category::Nature,
        Category::Food,
        Category::Activity,
        Category::Travel,
        Category::Objects,
        Category::Symbols,
        Category::Flags,
    ];

    /// Fluxer's key for the category (`people`, `nature`, ...). Display names are
    /// translated by the app.
    #[must_use]
    pub const fn key(self) -> &'static str {
        match self {
            Category::People => "people",
            Category::Nature => "nature",
            Category::Food => "food",
            Category::Activity => "activity",
            Category::Travel => "travel",
            Category::Objects => "objects",
            Category::Symbols => "symbols",
            Category::Flags => "flags",
        }
    }
}

/// One Unicode emoji.
#[derive(Debug, PartialEq, Eq)]
pub struct Emoji {
    /// The emoji as text, fully qualified (with `U+FE0F` where Unicode asks for it).
    pub glyph: &'static str,
    /// Shortcodes without colons. The first is the main one.
    pub names: &'static [&'static str],
    pub category: Category,
    /// Whether the emoji has skin tone variants.
    pub skin_tones: bool,
}

impl Emoji {
    /// The main shortcode, without colons.
    #[must_use]
    pub fn name(&self) -> &'static str {
        self.names[0]
    }
}

/// The five Fitzpatrick skin tones, as Fluxer's `skin-tone-1` to `skin-tone-5`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum SkinTone {
    /// The yellow default; leaves the emoji as it is.
    #[default]
    Default,
    Light,
    MediumLight,
    Medium,
    MediumDark,
    Dark,
}

impl SkinTone {
    /// The five real tones, light to dark.
    pub const TONES: [SkinTone; 5] = [
        SkinTone::Light,
        SkinTone::MediumLight,
        SkinTone::Medium,
        SkinTone::MediumDark,
        SkinTone::Dark,
    ];

    /// Fluxer's number for the tone (`skin-tone-N`): 1 to 5, or `None` for the default.
    #[must_use]
    pub const fn number(self) -> Option<u8> {
        match self {
            SkinTone::Default => None,
            SkinTone::Light => Some(1),
            SkinTone::MediumLight => Some(2),
            SkinTone::Medium => Some(3),
            SkinTone::MediumDark => Some(4),
            SkinTone::Dark => Some(5),
        }
    }

    /// The tone for Fluxer's number, 1 to 5.
    #[must_use]
    pub const fn from_number(n: u8) -> Option<SkinTone> {
        match n {
            1 => Some(SkinTone::Light),
            2 => Some(SkinTone::MediumLight),
            3 => Some(SkinTone::Medium),
            4 => Some(SkinTone::MediumDark),
            5 => Some(SkinTone::Dark),
            _ => None,
        }
    }

    /// The Unicode modifier (`U+1F3FB` to `U+1F3FF`), or `None` for the default.
    #[must_use]
    pub const fn modifier(self) -> Option<char> {
        match self {
            SkinTone::Default => None,
            SkinTone::Light => Some('\u{1F3FB}'),
            SkinTone::MediumLight => Some('\u{1F3FC}'),
            SkinTone::Medium => Some('\u{1F3FD}'),
            SkinTone::MediumDark => Some('\u{1F3FE}'),
            SkinTone::Dark => Some('\u{1F3FF}'),
        }
    }
}

/// Every emoji in picker order.
#[must_use]
pub fn all() -> &'static [Emoji] {
    &EMOJIS
}

/// The emoji grouped by category, in picker order.
#[must_use]
pub fn categories() -> &'static [(Category, &'static [Emoji])] {
    static CATEGORIES: OnceLock<Vec<(Category, &'static [Emoji])>> = OnceLock::new();
    CATEGORIES.get_or_init(|| {
        CATEGORY_RANGES
            .iter()
            .map(|&(category, start, end)| (category, &EMOJIS[start..end]))
            .collect()
    })
}

fn names() -> &'static HashMap<&'static str, usize> {
    static NAMES: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    NAMES.get_or_init(|| {
        let mut map = HashMap::with_capacity(EMOJIS.len() * 2);
        for (index, emoji) in EMOJIS.iter().enumerate() {
            for name in emoji.names {
                map.insert(*name, index);
            }
        }
        map
    })
}

fn strip_colons(name: &str) -> &str {
    let name = name.strip_prefix(':').unwrap_or(name);
    name.strip_suffix(':').unwrap_or(name)
}

/// The emoji with this shortcode, with or without the surrounding colons. Names are
/// case sensitive, as in Fluxer.
#[must_use]
pub fn by_shortcode(name: &str) -> Option<&'static Emoji> {
    names().get(strip_colons(name)).map(|&index| &EMOJIS[index])
}

/// Like [`by_shortcode`], but also understands Fluxer's tone suffix
/// (`wave::skin-tone-3`) and returns the glyph to insert or draw.
#[must_use]
pub fn shortcode_glyph(name: &str) -> Option<Cow<'static, str>> {
    let name = strip_colons(name);
    if let Some(emoji) = by_shortcode(name) {
        return Some(Cow::Borrowed(emoji.glyph));
    }
    let (base, tone) = name.split_once("::skin-tone-")?;
    let tone = match tone.as_bytes() {
        [digit @ b'1'..=b'5'] => SkinTone::from_number(digit - b'0')?,
        _ => return None,
    };
    let emoji = by_shortcode(base)?;
    emoji.skin_tones.then(|| with_skin_tone(emoji, tone))
}

/// `U+FE0F` (emoji presentation) is optional in typed text, so glyphs are compared
/// without it.
pub(crate) fn strip_fe0f(glyph: &str) -> Cow<'_, str> {
    if glyph.contains('\u{FE0F}') {
        Cow::Owned(glyph.replace('\u{FE0F}', ""))
    } else {
        Cow::Borrowed(glyph)
    }
}

/// The emoji for a glyph, ignoring `U+FE0F`. The five single-tone variants give the base
/// emoji; the mixed-tone couples are not mapped (they are only known to [`glyphs`],
/// [`crate::emoji_only`] and [`crate::twemoji_svg`]).
#[must_use]
pub fn by_glyph(glyph: &str) -> Option<&'static Emoji> {
    static BY_GLYPH: OnceLock<HashMap<String, usize>> = OnceLock::new();
    let map = BY_GLYPH.get_or_init(|| {
        let mut map = HashMap::with_capacity(EMOJIS.len() * 3);
        for (index, emoji) in EMOJIS.iter().enumerate() {
            map.insert(strip_fe0f(emoji.glyph).into_owned(), index);
        }
        for (base, tones) in &SKINS {
            let index = map[strip_fe0f(base).as_ref()];
            for tone in tones {
                map.insert(strip_fe0f(tone).into_owned(), index);
            }
        }
        map
    });
    map.get(strip_fe0f(glyph).as_ref())
        .map(|&index| &EMOJIS[index])
}

/// The list's own spelling of a glyph (with `U+FE0F` where the list has it), for any glyph
/// the list knows, ignoring `U+FE0F` in the input.
pub(crate) fn qualified(glyph: &str) -> Option<&'static str> {
    static QUALIFIED: OnceLock<HashMap<String, &'static str>> = OnceLock::new();
    QUALIFIED
        .get_or_init(|| glyphs().map(|g| (strip_fe0f(g).into_owned(), g)).collect())
        .get(strip_fe0f(glyph).as_ref())
        .copied()
}

/// The emoji a text shortcut such as `:D` or `<3` stands for.
#[must_use]
pub fn by_shortcut(text: &str) -> Option<&'static Emoji> {
    let index = SHORTCUTS
        .binary_search_by(|(shortcut, _)| (*shortcut).cmp(text))
        .ok()?;
    by_shortcode(SHORTCUTS[index].1)
}

/// The glyph of `emoji` in the given tone. Emoji without tones, and the default tone,
/// give the glyph unchanged.
#[must_use]
pub fn with_skin_tone(emoji: &Emoji, tone: SkinTone) -> Cow<'static, str> {
    let Some(number) = tone.number() else {
        return Cow::Borrowed(emoji.glyph);
    };
    if !emoji.skin_tones {
        return Cow::Borrowed(emoji.glyph);
    }
    match SKINS.binary_search_by(|(base, _)| (*base).cmp(emoji.glyph)) {
        Ok(index) => Cow::Borrowed(SKINS[index].1[usize::from(number) - 1]),
        Err(_) => Cow::Borrowed(emoji.glyph),
    }
}

/// Search keywords of the emoji at `index`, lower case.
pub(crate) fn keywords(index: usize) -> &'static [&'static str] {
    KEYWORDS[index]
}

/// Every glyph the list knows, in no particular order: the emoji, their tone variants and
/// the mixed-tone couples. This is the set that has Twemoji drawings.
pub fn glyphs() -> impl Iterator<Item = &'static str> {
    EMOJIS
        .iter()
        .map(|emoji| emoji.glyph)
        .chain(SKINS.iter().flat_map(|(_, tones)| tones.iter().copied()))
        .chain(MIXED_TONE_GLYPHS.iter().copied())
}

include!(concat!(env!("OUT_DIR"), "/data_generated.rs"));
